import {draftOrder,recordInvoice,transition} from './orders.mjs';
const supplier={name:'',handle:'sagatooov'},orders=[];
let loaded=false,serverMode=false,connected=false;
async function request(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Error(data.error||'Сервер недоступен.');return data;}
async function load(){const data=await request('./api/orders');orders.splice(0,orders.length,...data.orders);serverMode=true;connected=data.connected;loaded=true;}

const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(v)+' ₸';
const statuses={draft:'Черновик · не отправлен',awaiting_payment:'Ожидает оплаты',paid:'Оплачен · отмечено вами',received:'Получен · отмечено вами',cancelled:'Отменён',sent:'Отправлен в Telegram',sending:'Отправка · не повторяйте',delivery_unknown:'Доставка не подтверждена · проверьте чат'};
export function supplierPanel(app,result,notify,source){
  const panel=document.createElement('section');panel.className='panel supplier-panel';
  const pending=orders.filter(o=>o.status==='awaiting_payment');
  panel.innerHTML=`<div class="panel-head"><h2>Заказ оптовику</h2><span class="badge neutral">${connected?'Telegram подключён':'Telegram не подключён здесь'}</span></div><p class="note">Подготовьте заказ и проверьте его перед отправкой. Получатель должен открыть <a href="https://t.me/qadam_ai_supply_bot" target="_blank" rel="noopener noreferrer">@qadam_ai_supply_bot</a> и нажать «Старт». ${serverMode?'<button class="button" id="sync-telegram">Обновить Telegram</button>':''}</p>${pending.length?`<div class="callout"><strong>Ожидают оплаты: ${pending.length}</strong> · ${money(pending.reduce((s,o)=>s+o.invoice.amount,0))}<br>Проверьте счёт и оплатите напрямую поставщику.</div>`:''}<details><summary>Подготовить заказ</summary><form id="supplier-form"><div class="supplier-fields"><label>Поставщик<input id="supplier-name" maxlength="120" required value="${esc(supplier.name)}" placeholder="Название компании"></label><label>Telegram поставщика<input id="supplier-handle" maxlength="33" required value="${esc(supplier.handle)}" placeholder="@username"></label></div><p class="meta">Один заказ — один поставщик. Оставьте только его товары, для остальных укажите 0.</p><div class="table-wrap"><table><thead><tr><th>Товар</th><th>Количество, шт.</th></tr></thead><tbody>${result.products.map(p=>`<tr><td>${esc(p.name)}<small class="meta"> · ${esc(p.sku)}</small></td><td><input class="order-quantity" data-sku="${esc(p.sku)}" aria-label="Количество: ${esc(p.name)}" type="number" min="0" max="1000000" step="1" value="${p.suggested??0}"></td></tr>`).join('')}</tbody></table></div><button class="button primary" type="submit">Подготовить текст заказа</button></form></details><div id="orders-list"></div><p class="meta">${serverMode?'Заказы сохранены на сервере.':'Сервер недоступен: черновики только в этой вкладке.'} Оплачиваете вы; бот не списывает деньги. Заказы не меняют складские остатки.</p>`;
  app.querySelector('.stats').after(panel);
  const draw=()=>{
    panel.querySelector('#orders-list').innerHTML=orders.map(o=>`<article class="order-item"><div class="panel-head"><strong>${esc(o.supplier.name)}</strong><span class="badge ${o.status==='awaiting_payment'?'warn':'neutral'}">${statuses[o.status]}</span></div><div class="meta">${o.source==='demo'?'Учебный заказ · ':''}@${esc(o.supplier.handle)} · оценка ${money(o.estimate)}, цена не подтверждена</div><details><summary>Текст заказа</summary><textarea readonly aria-label="Текст заказа ${esc(o.supplier.name)}">${esc(o.message)}</textarea><button class="button" data-copy="${o.id}">Скопировать текст</button><a class="button" href="https://t.me/${encodeURIComponent(o.supplier.handle)}" target="_blank" rel="noopener noreferrer">Открыть чат</a><p class="meta">Открытие чата не отправляет сообщение. Можно отправить текст вручную со своего аккаунта.</p>${o.status==='draft'?`<label class="form-control"><input type="checkbox" id="approve-${o.id}" ${!connected||o.source==='demo'?'disabled':''}> Подтверждаю состав и отправку @${esc(o.supplier.handle)}</label><button class="button primary" data-send="${o.id}" ${!connected||o.source==='demo'?'disabled':''}>Подтвердить и отправить ботом</button><p class="meta">${o.source==='demo'?'Учебный заказ: отправка запрещена.':!connected?'Отправка будет доступна после подключения сервера к Telegram.':'Цена уточняется поставщиком; это запрос на согласование.'}</p>`:''}</details>${['draft','sent','awaiting_payment'].includes(o.status)?`<details><summary>Поставщик прислал счёт</summary><p class="note">Внесите подтверждённые сумму и срок. Это ручная запись, не ответ Telegram-бота.</p><form data-invoice="${o.id}" class="invoice-form"><label>К оплате, ₸<input name="amount" type="number" min="0.01" step="0.01" required value="${o.invoice?.amount??''}"></label><label>Оплатить до<input name="due" type="date" required value="${o.invoice?.due??''}"></label><label>Комментарий к счёту<textarea name="note" maxlength="1000">${esc(o.invoice?.note??'')}</textarea></label><button class="button" type="submit">Сохранить напоминание</button></form></details>`:''}${o.invoice?`<div class="callout">${money(o.invoice.amount)} · срок ${o.invoice.due} · ${o.invoice.source==='telegram'?'Счёт из Telegram':'Внесено вручную'}${o.invoice.note?`<br>${esc(o.invoice.note)}`:''}</div>`:''}<div class="toolbar">${o.status==='awaiting_payment'?`<button class="button primary" data-order="${o.id}" data-status="paid">Я оплатил(а)</button>`:''}${o.status==='paid'?`<button class="button" data-order="${o.id}" data-status="received">Товар получен</button>`:''}${['draft','sent','awaiting_payment'].includes(o.status)?`<button class="button" data-order="${o.id}" data-status="cancelled">Отменить в плане</button>`:''}</div></article>`).join('');
    panel.querySelectorAll('[data-send]').forEach(b=>b.onclick=async()=>{
      const i=orders.findIndex(o=>o.id===b.dataset.send);if(!panel.querySelector('#approve-'+b.dataset.send).checked){notify('Сначала подтвердите состав и получателя.');return;}
      b.disabled=true;try{orders[i]=await request('./api/orders/'+orders[i].id,{action:'send',confirm:true,version:orders[i].version});refresh();notify('Заказ отправлен в Telegram.');}catch(e){await load().catch(()=>{});refresh();notify(e.message);}
    });
    panel.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(orders.find(o=>o.id===b.dataset.copy).message);notify('Текст скопирован. Сообщение не отправлено.');}catch{notify('Выделите текст заказа и скопируйте его вручную.');}});
    panel.querySelectorAll('[data-invoice]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{const i=orders.findIndex(o=>o.id===f.dataset.invoice);const invoice=Object.fromEntries(new FormData(f));orders[i]=serverMode?await request('./api/orders/'+orders[i].id,{action:'invoice',invoice,version:orders[i].version}):recordInvoice(orders[i],invoice);refresh();notify('Напоминание об оплате добавлено в план.');}catch(error){notify(error.message);}});
    panel.querySelectorAll('[data-order]').forEach(b=>b.onclick=async()=>{try{const i=orders.findIndex(o=>o.id===b.dataset.order);orders[i]=serverMode?await request('./api/orders/'+orders[i].id,{action:b.dataset.status,version:orders[i].version}):transition(orders[i],b.dataset.status);refresh();notify('Статус изменён вами. Остатки не изменены.');}catch(error){notify(error.message);}});
  };
  const refresh=()=>{panel.remove();supplierPanel(app,result,notify,source);};
  panel.querySelector('#supplier-form').onsubmit=async e=>{e.preventDefault();const submit=e.currentTarget.querySelector('[type=submit]');if(submit.disabled)return;submit.disabled=true;try{const quantities=Object.fromEntries([...panel.querySelectorAll('.order-quantity')].map(el=>[el.dataset.sku,el.value]));const draft=draftOrder({name:panel.querySelector('#supplier-name').value,handle:panel.querySelector('#supplier-handle').value},result.products,quantities);draft.source=source;Object.assign(supplier,draft.supplier);if(orders.some(o=>o.status==='draft'&&o.message===draft.message))throw Error('Такой черновик уже есть ниже.');const saved=serverMode?await request('./api/orders',{supplier:draft.supplier,lines:draft.lines,source}):draft;orders.unshift(saved);draw();notify('Черновик готов. Проверьте текст заказа.');}catch(error){notify(error.message);}finally{submit.disabled=false;}};
  panel.querySelector('#sync-telegram')?.addEventListener('click',async()=>{try{await request('./api/telegram/sync',{});await load();refresh();notify('Telegram обновлён.');}catch(e){notify(e.message);}});
  draw();
  if(!loaded){loaded=true;load().then(()=>{if(panel.isConnected)refresh();}).catch(()=>notify('Сервер заказов недоступен. Черновики временные.'));}
}

